		zap.Object("request", caddyhttp.LoggableHTTPRequest{Request: r}),
	)

	changed := rewr.Rewrite(r, repl)

	if changed {
		logger.Debug("rewrote request",
			zap.String("method", r.Method),
			zap.String("uri", r.RequestURI),
		)
	}

	return next.ServeHTTP(w, r)
}

// rewrite performs the rewrites on r using repl, which should
// have been obtained from r, but is passed in for efficiency.
// It returns true if any changes were made to r.
func (rewr Rewrite) Rewrite(r *http.Request, repl *caddy.Replacer) bool {
	subs := make([]caddy.URISubstringSpec, len(rewr.URISubstring))
	for i, s := range rewr.URISubstring {
		subs[i] = caddy.URISubstringSpec{Find: s.Find, Replace: s.Replace, Limit: s.Limit}
	}
	regs := make([]caddy.URIRegexpSpec, len(rewr.PathRegexp))
	for i, p := range rewr.PathRegexp {
		if p == nil {
			continue
		}
		regs[i] = caddy.URIRegexpSpec{Find: p.Find, Replace: p.Replace, Pattern: p.re}
	}
	repl.PrepareURIRewrite(rewr.Method, rewr.URI, rewr.StripPathPrefix, rewr.StripPathSuffix, subs, regs)
	return repl.ExecuteURIRewrite(r)
}

func applyURIDirective(args []string) (Rewrite, error) {
	dir, err := caddy.NewEmptyReplacer().DecodeURIDirective(args)
	if err != nil {
		return Rewrite{}, err
	}
	var rewr Rewrite
	switch dir.Kind {
	case "strip_prefix":
		rewr.StripPathPrefix = dir.StripPrefix
	case "strip_suffix":
		rewr.StripPathSuffix = dir.StripSuffix
	case "replace":
		rewr.URISubstring = []substrReplacer{{
			Find:    dir.Find,
			Replace: dir.Replace,
			Limit:   dir.Limit,
		}}
	case "path_regexp":
		rewr.PathRegexp = []*regexReplacer{{
			Find:    dir.Find,
			Replace: dir.Replace,
		}}
	default:
		return Rewrite{}, fmt.Errorf("unrecognized URI manipulation '%s'", dir.Kind)
	}
	return rewr, nil
}

// substrReplacer describes either a simple and fast substring replacement.
type substrReplacer struct {
	// A substring to find. Supports placeholders.
	Find string `json:"find,omitempty"`

	// The substring to replace with. Supports placeholders.
	Replace string `json:"replace,omitempty"`

	// Maximum number of replacements per string.
	// Set to <= 0 for no limit (default).
	Limit int `json:"limit,omitempty"`
}


// regexReplacer describes a replacement using a regular expression.
type regexReplacer struct {
	// The regular expression to find.
	Find string `json:"find,omitempty"`

	// The substring to replace with. Supports placeholders and
	// regular expression capture groups.
	Replace string `json:"replace,omitempty"`

	re *regexp.Regexp
}


// Interface guard
var _ caddyhttp.MiddlewareHandler = (*Rewrite)(nil)

